package main
import("bytes";"encoding/json";"fmt";"os";mp4 "github.com/abema/go-mp4";"github.com/abema/go-mp4/task_support/fixture")
func main(){if e:=run();e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func check(b []byte,r *mp4.AVCEditReport)error{if r==nil||r.MediaTimescale==0||r.MovieTimescale==0||len(r.Edits)==0||len(r.Samples)==0{return fmt.Errorf("empty report")};visible:=0;idr:=false;for _,s:=range r.Samples{if s.SourceSample==0||int(s.EditIndex)>=len(r.Edits)||s.ByteSize<5||s.ByteOffset>uint64(len(b))||s.ByteSize>uint64(len(b))-s.ByteOffset{return fmt.Errorf("invalid sample range")};p:=b[s.ByteOffset:s.ByteOffset+s.ByteSize];if !bytes.HasPrefix(p,[]byte{0,0,0,1}){return fmt.Errorf("missing startcode")};for i:=0;i+4<len(p);i++{if bytes.Equal(p[i:i+4],[]byte{0,0,0,1})&&p[i+4]&31==5{idr=true}};if s.Visible{visible++;if s.VisibleDen!=r.MediaTimescale||s.VisibleEndNum<=s.VisibleStartNum{return fmt.Errorf("bad visible interval")}}};if visible==0||!idr{return fmt.Errorf("no visible IDR-bearing stream")};return nil}
func run()error{if len(os.Args)==3{b,e:=os.ReadFile(os.Args[1]);if e!=nil{return e};j,e:=os.ReadFile(os.Args[2]);if e!=nil{return e};var r mp4.AVCEditReport;if e=json.Unmarshal(j,&r);e!=nil{return e};if e=check(b,&r);e!=nil{return e};fmt.Println("CLI_FRESH_OUTPUT_OK");return nil};b,t,e:=fixture.Open();if e!=nil{return e};rdr:=bytes.NewReader(b);if _,e=rdr.Seek(7,0);e!=nil{return e};var out bytes.Buffer;report,e:=mp4.ExportAVCEdits(rdr,&out,t.TrackID);if e!=nil{return e};pos,e:=rdr.Seek(0,1);if e!=nil||pos!=7{return fmt.Errorf("reader position not restored")};if e=check(out.Bytes(),report);e!=nil{return e};if report.MediaTimescale!=t.Timescale{return fmt.Errorf("wrong source timescale")};src,e:=fixture.Payload(b,t);if e!=nil{return e};var idr []byte;for len(src)>=4{n:=int(uint32(src[0])<<24|uint32(src[1])<<16|uint32(src[2])<<8|uint32(src[3]));src=src[4:];if n<=0||n>len(src){return fmt.Errorf("source NAL range")};if src[0]&31==5{idr=append([]byte(nil),src[:n]...);break};src=src[n:]};if len(idr)==0||!bytes.Contains(out.Bytes(),append([]byte{0,0,0,1},idr...)){return fmt.Errorf("source IDR payload lost")};fmt.Printf("API_NORMAL_OK samples=%d bytes=%d\n",len(report.Samples),out.Len());return nil}
